/*
 * The UI font: JetBrains Mono Regular at 20 px, anti-aliased, printable
 * ASCII only, each character a FONT_W x FONT_H cell of 4-bit alpha. The
 * glyphs are in font.c, generated by mk/font-gen.py from the TTF (SIL
 * OFL 1.1, see font.c).
 */
#ifndef UI_FONT_H
#define UI_FONT_H

#include <stdint.h>

#define FONT_W     12
#define FONT_H     24
#define FONT_FIRST 0x20
#define FONT_LAST  0x7e

/* Rows top to bottom, two pixels a byte, the left one in the high
 * nibble; 0 is clear, 15 opaque. */
extern const uint8_t font_glyphs[FONT_LAST - FONT_FIRST + 1][FONT_H][FONT_W / 2];

#endif
